package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"net/http"
	"regexp"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/campaign"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// HTTP-level error codes of the campaign routes.
const (
	codeNotFound          = "not_found"
	codeVersionConflict   = "version_conflict"
	codeInvalidTransition = "invalid_transition"
)

// actor is who the audit trail names. There is one admin token, so there is
// one actor.
const actor = "admin"

var uuidPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

// campaignRoutes registers the stage 0 campaign routes. Generate, approve
// and the read APIs of later stages go in their own files.
func (s *Server) campaignRoutes(api *http.ServeMux) {
	api.HandleFunc("POST /api/campaigns", s.createCampaign)
	api.HandleFunc("GET /api/campaigns/{id}", s.withCampaignID(s.getCampaign))
	api.HandleFunc("POST /api/campaigns/{id}/revisions", s.withCampaignID(s.editCampaign))
	api.HandleFunc("POST /api/campaigns/{id}/reject", s.withCampaignID(s.versionAction(campaign.Reject)))
	api.HandleFunc("POST /api/campaigns/{id}/cancel", s.withCampaignID(s.versionAction(s.cancel)))
}

// withCampaignID answers 404 for an id that is not a UUID, so it never
// reaches a query.
func (s *Server) withCampaignID(h func(http.ResponseWriter, *http.Request, string)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")
		if !uuidPattern.MatchString(id) {
			writeError(w, http.StatusNotFound, codeNotFound, "campaign not found")
			return
		}
		h(w, r, id)
	}
}

// decodeBody reads one JSON value. On failure it has written the response.
func decodeBody(w http.ResponseWriter, r *http.Request) (any, bool) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	doc, err := schema.Decode(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, codeBodyTooLarge, "body is larger than 64 KiB")
			return nil, false
		}
		writeError(w, http.StatusBadRequest, validation.InvalidJSON, err.Error())
		return nil, false
	}
	return doc, true
}

// fields checks that doc is an object with exactly the required keys.
func fields(doc any, res *validation.Result, keys ...string) map[string]any {
	m, ok := doc.(map[string]any)
	if !ok {
		res.Error("", validation.InvalidType, "expected an object")
		return nil
	}
	allowed := map[string]bool{}
	for _, k := range keys {
		allowed[k] = true
		if _, ok := m[k]; !ok {
			res.Error("/"+k, validation.Required, fmt.Sprintf("missing required key %q", k))
		}
	}
	for k := range m {
		if !allowed[k] {
			res.Error("/"+k, validation.UnknownProperty, fmt.Sprintf("key %q is not allowed", k))
		}
	}
	return m
}

// version reads the campaign version a client sends back.
func version(m map[string]any, res *validation.Result) int {
	v, present := m["version"]
	if !present {
		return 0 // reported by fields
	}
	n, ok := v.(json.Number)
	i, err := n.Int64()
	if !ok || err != nil || i < 0 || i > math.MaxInt32 {
		res.Error("/version", validation.InvalidType, "expected a non-negative integer")
		return 0
	}
	return int(i)
}

// campaignView is a campaign with its current revision and audit trail.
type campaignView struct {
	Campaign store.Campaign  `json:"campaign"`
	Revision *store.Revision `json:"revision"`
	Events   []store.Event   `json:"events"`
}

func (s *Server) loadView(ctx context.Context, id string) (campaignView, error) {
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	var v campaignView
	var err error
	if v.Campaign, err = store.GetCampaign(ctx, s.Pool, id); err != nil {
		return v, err
	}
	if v.Campaign.CurrentRevisionID != nil {
		rev, err := store.GetRevision(ctx, s.Pool, id, *v.Campaign.CurrentRevisionID)
		if err != nil {
			return v, err
		}
		v.Revision = &rev
	}
	if v.Events, err = store.ListCampaignEvents(ctx, s.Pool, id); err != nil {
		return v, err
	}
	if v.Events == nil {
		v.Events = []store.Event{}
	}
	return v, nil
}

// writeView answers with the campaign as it is now.
func (s *Server) writeView(w http.ResponseWriter, r *http.Request, status int, id string) {
	v, err := s.loadView(r.Context(), id)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	writeJSON(w, status, v)
}

// fail maps a campaign error to its status code.
func (s *Server) fail(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, campaign.ErrNotFound):
		writeError(w, http.StatusNotFound, codeNotFound, "campaign not found")
	case errors.Is(err, campaign.ErrConflict):
		writeError(w, http.StatusConflict, codeVersionConflict, "the campaign changed; reload it and try again")
	case errors.Is(err, campaign.ErrInvalidTransition):
		writeError(w, http.StatusConflict, codeInvalidTransition, "the campaign's state does not allow this action")
	default:
		s.Log.Error("campaign request failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "the request failed")
	}
}

func (s *Server) createCampaign(w http.ResponseWriter, r *http.Request) {
	doc, ok := decodeBody(w, r)
	if !ok {
		return
	}
	n, res := campaign.ValidateNew(doc, s.Config.CampaignURLHosts)
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	c, err := campaign.Create(ctx, s.Pool, n, actor)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.writeView(w, r, http.StatusCreated, c.ID)
}

func (s *Server) getCampaign(w http.ResponseWriter, r *http.Request, id string) {
	s.writeView(w, r, http.StatusOK, id)
}

// cancel cancels the campaign and, through River, its generate job.
func (s *Server) cancel(ctx context.Context, db campaign.Beginner, id string, version int, actor string) error {
	var jc campaign.JobCanceller
	if s.River != nil {
		jc = s.River
	}
	return campaign.CancelWithJobs(ctx, db, jc, id, version, actor)
}

// versionAction serves an action whose body is {"version": n}.
func (s *Server) versionAction(action func(context.Context, campaign.Beginner, string, int, string) error) func(http.ResponseWriter, *http.Request, string) {
	return func(w http.ResponseWriter, r *http.Request, id string) {
		doc, ok := decodeBody(w, r)
		if !ok {
			return
		}
		var res validation.Result
		m := fields(doc, &res, "version")
		v := version(m, &res)
		if !res.OK() {
			writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
		defer cancel()
		if err := action(ctx, s.Pool, id, v, actor); err != nil {
			s.fail(w, r, err)
			return
		}
		s.writeView(w, r, http.StatusOK, id)
	}
}

// editCampaign stores a human edit. It goes through the same validator as
// LLM output (rule 7); an invalid edit gets 422 and is never stored.
func (s *Server) editCampaign(w http.ResponseWriter, r *http.Request, id string) {
	doc, ok := decodeBody(w, r)
	if !ok {
		return
	}
	var res validation.Result
	m := fields(doc, &res, "base_revision_id", "version", "revision")
	v := version(m, &res)
	base, isString := m["base_revision_id"].(string)
	if _, present := m["base_revision_id"]; present && !isString {
		res.Error("/base_revision_id", validation.InvalidType, "expected a string")
	}
	var rev campaign.Revision
	var revRes validation.Result // its paths are relative to the revision, as stored
	if raw, present := m["revision"]; present {
		rev, revRes = campaign.ValidateRevision(s.Schemas, raw)
		for _, is := range revRes.Errors {
			res.Error("/revision"+is.Path, is.Code, is.Message)
		}
	}
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	_, err := campaign.SaveEdit(ctx, s.Pool, campaign.Edit{
		ID:             id,
		BaseRevisionID: base,
		Version:        v,
		Revision:       rev,
		Warnings:       revRes.Warnings,
		Actor:          actor,
		AsOf:           s.Now().UTC(),
	})
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.writeView(w, r, http.StatusCreated, id)
}

//go:build spec

package store

import (
	"context"
	"testing"
)

// Plan 3, 1.1: LatestStartedEventID finds the newest started event of a
// campaign, so the campaign view can rebuild the events URL after a page
// refresh. ok is false when the campaign never had a generation.
func TestLatestStartedEventID(t *testing.T) {
	p, _ := seededPool(t)
	ctx := context.Background()
	a, b := newCampaignID(t, p), newCampaignID(t, p)

	if _, ok, err := LatestStartedEventID(ctx, p, a); err != nil || ok {
		t.Fatalf("no events: ok=%v err=%v, want ok=false", ok, err)
	}

	add := func(id, typ string) int64 {
		t.Helper()
		n, err := InsertGenerationEvent(ctx, p, id, typ, map[string]any{})
		if err != nil {
			t.Fatal(err)
		}
		return n
	}
	first := add(a, "started")
	add(a, "segment_ready")
	add(a, "done")
	if got, ok, err := LatestStartedEventID(ctx, p, a); err != nil || !ok || got != first {
		t.Fatalf("one generation: %d ok=%v err=%v, want %d", got, ok, err, first)
	}

	// A later started event of another campaign does not count.
	add(b, "started")
	if got, _, _ := LatestStartedEventID(ctx, p, a); got != first {
		t.Errorf("another campaign's started moved the cursor to %d", got)
	}

	second := add(a, "started")
	add(a, "delta")
	if got, ok, err := LatestStartedEventID(ctx, p, a); err != nil || !ok || got != second {
		t.Errorf("second generation: %d ok=%v err=%v, want %d", got, ok, err, second)
	}

	// Only started counts, never the newest event of any type.
	if _, ok, _ := LatestStartedEventID(ctx, p, b); !ok {
		t.Error("campaign b has a started event")
	}
	c := newCampaignID(t, p)
	add(c, "delta")
	if _, ok, _ := LatestStartedEventID(ctx, p, c); ok {
		t.Error("a campaign with events but no started has no cursor")
	}
}
//go:build spec

package httpapi

import (
	"encoding/json"
	"net/http"
	"testing"
)

// Plan 3, 1.1: the campaign view carries
// "generation": {"events_url": "/api/campaigns/{id}/events?after=N"}, N being
// the latest started event id minus 1, or null before the first generation.
// The UI never builds an events URL itself.

func viewEventsURL(t *testing.T, view map[string]any) (string, bool) {
	t.Helper()
	g, present := view["generation"]
	if !present {
		t.Fatalf("campaign view has no generation key: %v", view)
	}
	if g == nil {
		return "", false
	}
	u, ok := g.(map[string]any)["events_url"].(string)
	if !ok {
		t.Fatalf("generation has no events_url: %v", g)
	}
	return u, true
}

// A campaign that never generated has generation: null, also through the
// 201 of create.
func TestViewGenerationNullBeforeFirstGeneration(t *testing.T) {
	h, p := campaignAPI(t)
	rec := do(h, "POST", "/api/campaigns", createBody("brief", okURL), bearer)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: %d %s", rec.Code, rec.Body)
	}
	v := decodeView(t, rec)
	_, code, body := getView(t, h, v.Campaign.ID)
	if code != http.StatusOK {
		t.Fatalf("get: %d", code)
	}
	if _, ok := viewEventsURL(t, body); ok {
		t.Errorf("never generated, but the view has a cursor: %v", body["generation"])
	}
	f := insertCampaign(t, p, "in_review", 1)
	if _, _, body := getView(t, h, f.ID); body["generation"] != nil {
		t.Errorf("fixture without events: generation %v, want null", body["generation"])
	}
}

// After a generate, and again after a second one, the view's URL equals
// the one in the 202.
func TestViewGenerationMatchesGenerate(t *testing.T) {
	h, p := generateAPI(t)
	f := insertCampaign(t, p, "in_review", 2)

	first := generateURL(t, h, f.ID, 2)
	if got, _, body := getView(t, h, f.ID); got != first {
		t.Errorf("after the first generate: view %q, 202 %q (%v)", got, first, body["generation"])
	}

	// The first generation ends; the campaign goes back to review.
	if _, err := p.Exec(t.Context(), `UPDATE campaigns SET state = 'in_review', version = 4 WHERE id = $1`, f.ID); err != nil {
		t.Fatal(err)
	}
	addGenEvent(t, p, f.ID, "done", map[string]any{})
	if got, _, _ := getView(t, h, f.ID); got != first {
		t.Errorf("in review after the first generation: view %q, want %q still", got, first)
	}

	second := generateURL(t, h, f.ID, 4)
	if second == first {
		t.Fatalf("second generate returned the first cursor %q", first)
	}
	if got, _, _ := getView(t, h, f.ID); got != second {
		t.Errorf("after the second generate: view %q, 202 %q", got, second)
	}
}

// Reading the view's URL during a second generation never yields the
// first generation's terminal event: it starts at the new started event.
func TestViewGenerationSkipsOlderGeneration(t *testing.T) {
	srv, _, _ := liveStack(t)
	code, created := apiCall(t, srv, "POST", "/api/campaigns", createBody(specBrief, okURL))
	if code != http.StatusCreated {
		t.Fatalf("create: %d %v", code, created)
	}
	id := created["campaign"].(map[string]any)["id"].(string)
	firstRun := sseCollect(t, srv, startGenerate(t, srv, id, 0), bearer)
	firstDone := firstRun[len(firstRun)-1]
	if firstDone.Event != "done" {
		t.Fatalf("first generation ended with %q", firstDone.Event)
	}

	_, view := apiCall(t, srv, "GET", "/api/campaigns/"+id, "")
	version := int(view["campaign"].(map[string]any)["version"].(float64))
	startGenerate(t, srv, id, version)

	_, view = apiCall(t, srv, "GET", "/api/campaigns/"+id, "")
	u, ok := viewEventsURL(t, view)
	if !ok || !isEventsURL(u, id) {
		t.Fatalf("mid-generation view: generation %v", view["generation"])
	}
	events := sseCollect(t, srv, u, bearer)
	if len(events) == 0 || events[0].Event != "started" {
		t.Fatalf("stream from the view starts with %+v, want started", events)
	}
	for _, e := range events {
		if e.ID <= firstDone.ID {
			t.Errorf("event %d (%s) belongs to the first generation", e.ID, e.Event)
		}
	}
	if last := events[len(events)-1]; last.Event != "done" {
		t.Errorf("second stream ended with %q", last.Event)
	}
}

func getView(t *testing.T, h http.Handler, id string) (string, int, map[string]any) {
	t.Helper()
	rec := do(h, "GET", "/api/campaigns/"+id, "", bearer)
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("view: %s", rec.Body)
	}
	if rec.Code != http.StatusOK {
		return "", rec.Code, body
	}
	u, _ := viewEventsURL(t, body)
	return u, rec.Code, body
}

func generateURL(t *testing.T, h http.Handler, id string, version int) string {
	t.Helper()
	rec := do(h, "POST", "/api/campaigns/"+id+"/generate", versionBody(version), bearer)
	var body struct {
		EventsURL string `json:"events_url"`
	}
	if rec.Code != http.StatusAccepted || json.Unmarshal(rec.Body.Bytes(), &body) != nil || !isEventsURL(body.EventsURL, id) {
		t.Fatalf("generate: %d %s", rec.Code, rec.Body)
	}
	return body.EventsURL
}
package store

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
)

// GenerationEventsChannel is the LISTEN channel of the event log. The
// payload is the campaign id.
const GenerationEventsChannel = "generation_events"

// GenerationEvent is a generation_events row.
type GenerationEvent struct {
	ID         int64           `json:"id"`
	CampaignID string          `json:"campaign_id"`
	Type       string          `json:"type"`
	Payload    json.RawMessage `json:"payload"`
	CreatedAt  time.Time       `json:"created_at"`
}

// InsertGenerationEvent appends an event and notifies listeners. Postgres
// delivers the notification only when the transaction commits, so pass a
// transaction to make the event part of a larger change.
func InsertGenerationEvent(ctx context.Context, db DB, campaignID, typ string, payload any) (int64, error) {
	b, err := json.Marshal(payload)
	if err != nil {
		return 0, err
	}
	var id int64
	if err := db.QueryRow(ctx, `INSERT INTO generation_events (campaign_id, type, payload) VALUES ($1, $2, $3) RETURNING id`,
		campaignID, typ, string(b)).Scan(&id); err != nil {
		return 0, err
	}
	_, err = db.Exec(ctx, `SELECT pg_notify($1, $2)`, GenerationEventsChannel, campaignID)
	return id, err
}

// ListGenerationEvents returns a campaign's events with an id above after,
// oldest first.
func ListGenerationEvents(ctx context.Context, db DB, campaignID string, after int64) ([]GenerationEvent, error) {
	rows, err := db.Query(ctx, `SELECT id, campaign_id::text, type, payload, created_at FROM generation_events
		WHERE campaign_id = $1 AND id > $2 ORDER BY id`, campaignID, after)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rows, func(r pgx.CollectableRow) (GenerationEvent, error) {
		var e GenerationEvent
		err := r.Scan(&e.ID, &e.CampaignID, &e.Type, &e.Payload, &e.CreatedAt)
		return e, err
	})
}

// LockGenerating locks a campaign row against transitions for the rest of
// the transaction, if the campaign is still generating at version. A
// generation job writes nothing unless this holds, so a cancel or a newer
// generation always wins.
func LockGenerating(ctx context.Context, db DB, id string, version int) (bool, error) {
	var one int
	err := db.QueryRow(ctx, `SELECT 1 FROM campaigns WHERE id = $1 AND state = 'generating' AND version = $2 FOR SHARE`,
		id, version).Scan(&one)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	return err == nil, err
}

// LLMCall is one llm_calls row to insert.
type LLMCall struct {
	CampaignID       string
	Stage            string
	Attempt          int
	Outcome          string // valid, invalid, refusal, max_tokens, transport_error
	ErrorClass       string // empty unless transport_error
	StopReason       string
	Model            string
	InputTokens      *int
	OutputTokens     *int
	LatencyMS        int
	RawOutput        string
	ValidationErrors any // a JSON array
	PromptVersion    string
}

// InsertLLMCall records one call to the model.
func InsertLLMCall(ctx context.Context, db DB, c LLMCall) error {
	errs, err := json.Marshal(c.ValidationErrors)
	if err != nil {
		return err
	}
	if c.ValidationErrors == nil {
		errs = []byte("[]")
	}
	_, err = db.Exec(ctx, `INSERT INTO llm_calls (campaign_id, stage, attempt, outcome, error_class, stop_reason, model,
