// Plan 3, 1.7: SSE through nginx, against the compose stack on :8081 in
// mock mode (make e2e). Uses the app's own src/api/sse.ts in Node.
//
// Env: WEB_URL (default http://127.0.0.1:8081), E2E_TOKEN (default the
// compose dev token). No API key: the stack runs LLM_MODE=mock.
//
// Contract assumed besides sse.ts (src/composables/useGeneration.ts):
//   useGeneration(opts: { baseUrl: string; token: string; fetch?: typeof fetch;
//                         getCampaign(id, signal): Promise<CampaignView> }): {
//     state: Ref<GenState>; view: Ref<CampaignView | null>; endedEarly: Ref<boolean>;
//     follow(campaignId: string, eventsUrl: string): Promise<void>  resolves once terminal or reconciled
//   }
import { describe, expect, it } from 'vitest'
import { effectScope } from 'vue'
import { openEventStream, type SSEMessage } from '../src/api/sse'
import { useGeneration } from '../src/composables/useGeneration'

const BASE = process.env.WEB_URL ?? 'http://127.0.0.1:8081'
const TOKEN = process.env.E2E_TOKEN ?? 'dev-admin-token'
const BRIEF = "Son 30 günde sepetine ürün ekleyip alışveriş yapmayan İstanbul'daki kullanıcılara %30 indirim hatırlatması gönder."
const HEARTBEAT_MS = 15_000

async function api(method: string, path: string, body?: unknown): Promise<any> {
  const res = await fetch(BASE + path, {
    method,
    headers: { Authorization: `Bearer ${TOKEN}`, 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  const text = await res.text()
  if (!res.ok) throw new Error(`${method} ${path}: ${res.status} ${text}`)
  return text ? JSON.parse(text) : null
}

async function createCampaign(): Promise<string> {
  const v = await api('POST', '/api/campaigns', { brief: BRIEF, campaign_url: 'https://shop.example/kampanya' })
  return v.campaign.id
}

async function generate(id: string): Promise<string> {
  const view = await api('GET', `/api/campaigns/${id}`)
  const r = await api('POST', `/api/campaigns/${id}/generate`, { version: view.campaign.version })
  return r.events_url
}

interface Seen {
  m: SSEMessage
  at: number
}

async function collect(url: string, opts: { lastEventId?: number; signal?: AbortSignal; onMessage?: (m: SSEMessage) => void } = {}) {
  const seen: Seen[] = []
  const comments: number[] = []
  const result = await openEventStream(BASE + url, {
    token: TOKEN,
    lastEventId: opts.lastEventId,
    signal: opts.signal,
    onMessage: (m) => {
      seen.push({ m, at: Date.now() })
      opts.onMessage?.(m)
    },
    onComment: () => comments.push(Date.now()),
  })
  return { seen, comments, result }
}

const ids = (s: Seen[]) => s.map((x) => Number(x.m.id))

async function untilState(id: string, states: string[], within = 30_000) {
  const end = Date.now() + within
  for (;;) {
    const v = await api('GET', `/api/campaigns/${id}`)
    if (states.includes(v.campaign.state)) return v
    if (Date.now() > end) throw new Error(`campaign ${id} is ${v.campaign.state}, want ${states}`)
    await new Promise((r) => setTimeout(r, 100))
  }
}

// An idle stream: after the last event of a finished generation, so the
// server waits for live events and sends only heartbeats.
async function idleStreamURL(): Promise<{ id: string; url: string }> {
  const id = await createCampaign()
  const first = await collect(await generate(id))
  const last = first.seen[first.seen.length - 1]
  expect(last.m.event).toBe('done')
  await untilState(id, ['in_review'])
  return { id, url: `/api/campaigns/${id}/events?after=${last.m.id}` }
}

describe('SSE through nginx', () => {
  // 1. The proxy does not buffer: a heartbeat comment, a few bytes long,
  // reaches the client while the stream is idle, and live events arrive on
  // the open stream in order.
  it('delivers heartbeats and live events without buffering', async () => {
    const { id, url } = await idleStreamURL()
    const ctl = new AbortController()
    const opened = Date.now()
    let firstComment = 0
    const events: SSEMessage[] = []
    const done = openEventStream(BASE + url, {
      token: TOKEN,
      signal: ctl.signal,
      onMessage: (m) => events.push(m),
      onComment: () => {
        if (!firstComment) firstComment = Date.now()
      },
    })
    await new Promise((r) => setTimeout(r, HEARTBEAT_MS + 3_000))
    expect(firstComment, 'no heartbeat came through the proxy').toBeGreaterThan(0)
    expect(firstComment - opened).toBeLessThanOrEqual(HEARTBEAT_MS + 3_000)
    expect(events).toEqual([])

    await generate(id)
    await expect(done).resolves.toBe('ended')
    expect(events[0].event).toBe('started')
    expect(events.at(-1)!.event).toBe('done')
    expect(events.some((e) => e.event === 'delta')).toBe(true)
  }, 60_000)

  // 2. Mid-run of a second generation, the campaign view's events_url never
  // yields the first generation's terminal event.
  it('the view cursor skips the first generation', async () => {
    const id = await createCampaign()
    const first = await collect(await generate(id))
    const firstDone = Number(first.seen.at(-1)!.m.id)
    await untilState(id, ['in_review'])
    await generate(id)
    const view = await api('GET', `/api/campaigns/${id}`)
    expect(view.generation?.events_url).toBeTruthy()
    const second = await collect(view.generation.events_url)
    expect(second.seen[0].m.event).toBe('started')
    expect(Math.min(...ids(second.seen))).toBeGreaterThan(firstDone)
    expect(second.seen.at(-1)!.m.event).toBe('done')
  }, 60_000)

  // 3. Drop the connection mid-stream and reconnect with Last-Event-ID:
  // every remaining event arrives exactly once.
  it('resumes with Last-Event-ID without loss or duplicates', async () => {
    const id = await createCampaign()
    const url = await generate(id)
    const ctl = new AbortController()
    const part = await collect(url, { signal: ctl.signal, onMessage: () => ctl.abort() })
    expect(part.result).toBe('aborted')
    expect(part.seen.length).toBeGreaterThanOrEqual(1)
    const lastSeen = Number(part.seen.at(-1)!.m.id)

    const rest = await collect(url, { lastEventId: lastSeen })
    const full = await collect(url)
    const joined = [...ids(part.seen), ...ids(rest.seen)]
    expect(new Set(joined).size).toBe(joined.length)
    expect(joined).toEqual(ids(full.seen))
    expect(rest.seen.at(-1)!.m.event).toBe('done')
  }, 60_000)

  // 4. A heartbeat keeps an idle stream open past nginx's default 60 s read
  // timeout (the config sets 1 h; heartbeats make the margin irrelevant).
  it('keeps an idle stream open past the proxy default timeout', async () => {
    const { id, url } = await idleStreamURL()
    const events: SSEMessage[] = []
    let comments = 0
    const done = openEventStream(BASE + url, {
      token: TOKEN,
      onMessage: (m) => events.push(m),
      onComment: () => comments++,
    })
    let ended = false
    done.then(() => (ended = true))
    await new Promise((r) => setTimeout(r, 70_000))
    expect(ended, 'the proxy closed an idle stream').toBe(false)
    expect(comments).toBeGreaterThanOrEqual(4)
    await generate(id)
    await expect(done).resolves.toBe('ended')
    expect(events[0].event).toBe('started')
  }, 120_000)

  // 5. A stream cut before its terminal event: the client reloads the
  // campaign view and reconciles, either by reconnecting (still generating)
  // or by rendering the stored revision with an early-end notice.
  it('reconciles from the campaign view when the stream is cut', async () => {
    const id = await createCampaign()
    const url = await generate(id)
    let connections = 0
    // The first connection is cut after its first frame, as a proxy reset would.
    const cutting: typeof fetch = async (input, init) => {
      const res = await fetch(input, init)
      if (!String(input).includes('/events') || connections++ > 0 || !res.body) return res
      const reader = res.body.getReader()
      let sent = false
      const body = new ReadableStream<Uint8Array>({
        async pull(c) {
          if (sent) {
            await reader.cancel()
            c.close()
            return
          }
          const { value, done } = await reader.read()
          if (done || !value) return c.close()
          const text = new TextDecoder().decode(value)
          const end = text.indexOf('\n\n')
          c.enqueue(new TextEncoder().encode(end >= 0 ? text.slice(0, end + 2) : text))
          sent = end >= 0
        },
      })
      return new Response(body, { status: res.status, headers: res.headers })
    }
    const scope = effectScope()
    const g = scope.run(() =>
      useGeneration({
        baseUrl: BASE,
        token: TOKEN,
        fetch: cutting,
        getCampaign: (cid, signal) =>
          fetch(`${BASE}/api/campaigns/${cid}`, { headers: { Authorization: `Bearer ${TOKEN}` }, signal }).then((r) => r.json()),
      }),
    )!
    await g.follow(id, url)
    scope.stop()

    const view = await untilState(id, ['in_review'])
    expect(connections).toBeGreaterThanOrEqual(1)
    if (g.endedEarly.value) {
      expect(g.view.value?.revision?.id).toBe(view.revision.id)
    } else {
      expect(connections).toBeGreaterThanOrEqual(2) // it reconnected
      expect(g.state.value.phase).toBe('done')
      expect(g.state.value.fields['sms.body']).toBe(view.revision.sms_body)
      expect(g.state.value.fields['email.subject']).toBe(view.revision.email_subject)
      expect(g.state.value.fields['email.body']).toBe(view.revision.email_body)
    }
  }, 60_000)
})

// Plan 3, 1.3: the edit contract. useDraft owns the unsaved text; campaign
// reloads never write into it, and a 409 keeps it.
//
// Contract assumed (src/composables/useDraft.ts, src/api/client.ts):
//   class ApiError extends Error { status: number; issues: Issue[] }
//   useDraft(): {
//     draft: Ref<{ sms: string; subject: string; body: string } | null>
//     dirty: ComputedRef<boolean>; conflict: Ref<boolean>; issues: Ref<IssueMap | null>
//     start(view): void       fills the draft only when it is empty
//     observe(view): void     every campaign reload; never touches the draft
//     body(): RevisionRequest
//     save(post: (body) => Promise<CampaignView>): Promise<'saved' | 'conflict' | 'invalid'>
//     rebase(latest): void    "Save on top of latest": new base, same text
//     useLatest(latest): void "Use latest": discard the draft
//   }
import { describe, expect, it, vi } from 'vitest'
import { effectScope } from 'vue'
import { ApiError } from '../api/client'
import { useDraft } from './useDraft'

const segment = { version: 1, match: 'all', conditions: [{ kind: 'enum_attribute', field: 'city', op: 'eq', value: 'istanbul' }] }

function view(revisionId: string, version: number, copy = { sms: 'Merhaba {{campaign_url}}', subject: 'Sepet', body: 'Selam {{campaign_url}}' }, seg: unknown = segment) {
  return {
    campaign: { id: 'c1', state: 'in_review', version, current_revision_id: revisionId },
    revision: { id: revisionId, n: 1, source: 'llm', segment: seg, sms_body: copy.sms, email_subject: copy.subject, email_body: copy.body },
    events: [],
    generation: null,
  } as any
}

function withDraft() {
  const scope = effectScope()
  const d = scope.run(() => useDraft())!
  return { d, scope }
}

describe('useDraft', () => {
  it('starts from the current revision and tracks edits', () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    expect(d.draft.value).toEqual({ sms: 'Merhaba {{campaign_url}}', subject: 'Sepet', body: 'Selam {{campaign_url}}' })
    expect(d.dirty.value).toBe(false)
    d.draft.value!.sms = 'Merhaba {{first_name}} {{campaign_url}}'
    expect(d.dirty.value).toBe(true)
  })

  it('builds the exact request body, with the segment copied from the base revision', () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.subject = 'Yeni konu'
    expect(d.body()).toEqual({
      base_revision_id: 'r1',
      version: 3,
      revision: {
        segment,
        content: { sms: { body: 'Merhaba {{campaign_url}}' }, email: { subject: 'Yeni konu', body: 'Selam {{campaign_url}}' } },
      },
    })
  })

  it('never lets a reload overwrite the draft', () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.sms = 'my edit {{campaign_url}}'
    d.observe(view('r2', 5, { sms: 'server copy', subject: 'server', body: 'server' }))
    d.start(view('r2', 5, { sms: 'server copy', subject: 'server', body: 'server' }))
    expect(d.draft.value!.sms).toBe('my edit {{campaign_url}}')
    expect(d.body().base_revision_id).toBe('r1')
  })

  it('keeps the draft on a 409 and reports the conflict', async () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.sms = 'my edit {{campaign_url}}'
    const post = vi.fn(async () => {
      throw new ApiError(409, [{ path: '', code: 'version_conflict', message: 'the campaign changed' }])
    })
    await expect(d.save(post)).resolves.toBe('conflict')
    expect(d.conflict.value).toBe(true)
    expect(d.draft.value!.sms).toBe('my edit {{campaign_url}}')
    expect(d.dirty.value).toBe(true)
  })

  it('keeps the draft on a 422 and maps the issues to fields', async () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.sms = 'go to https://evil.example'
    const post = vi.fn(async () => {
      throw new ApiError(422, [
        { path: '/revision/content/sms/body', code: 'contains_url', message: 'no links' },
        { path: '/version', code: 'invalid_type', message: 'x' },
      ])
    })
    await expect(d.save(post)).resolves.toBe('invalid')
    expect(d.issues.value!.sms.map((i) => i.code)).toEqual(['contains_url'])
    expect(d.issues.value!.form.map((i) => i.path)).toEqual(['/version'])
    expect(d.draft.value!.sms).toBe('go to https://evil.example')
  })

  it('saves on top of latest with the new base and version, keeping the text', async () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.body = 'my body {{campaign_url}}'
    await d.save(async () => {
      throw new ApiError(409, [])
    })
    const latestSegment = { ...segment, match: 'any' }
    d.rebase(view('r2', 6, { sms: 'theirs', subject: 'theirs', body: 'theirs' }, latestSegment))
    expect(d.conflict.value).toBe(false)
    const b = d.body()
    expect(b.base_revision_id).toBe('r2')
    expect(b.version).toBe(6)
    expect(b.revision.segment).toEqual(latestSegment)
    expect(b.revision.content.email.body).toBe('my body {{campaign_url}}')
  })

  it('discards the draft only through useLatest', () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.sms = 'mine'
    d.useLatest(view('r2', 6, { sms: 'theirs', subject: 's', body: 'b' }))
    expect(d.draft.value).toEqual({ sms: 'theirs', subject: 's', body: 'b' })
    expect(d.dirty.value).toBe(false)
    expect(d.body().base_revision_id).toBe('r2')
  })

  it('re-bases on the saved revision after a successful save', async () => {
    const { d } = withDraft()
    d.start(view('r1', 3))
    d.draft.value!.sms = 'new {{campaign_url}}'
    const post = vi.fn(async () => view('r3', 4, { sms: 'new {{campaign_url}}', subject: 'Sepet', body: 'Selam {{campaign_url}}' }))
    await expect(d.save(post)).resolves.toBe('saved')
    expect(post).toHaveBeenCalledTimes(1)
    expect(d.dirty.value).toBe(false)
    expect(d.issues.value).toBeNull()
    expect(d.body().base_revision_id).toBe('r3')
    expect(d.body().version).toBe(4)
  })
})
// Plan 3, 1.4: the delivery polling contract, with fake timers.
//
// Contract assumed (src/composables/useDeliveryPolling.ts):
//   PollingApi {
//     getCampaign(id, signal): Promise<CampaignView>
//     getStats(id, signal): Promise<{ channels: Record<string, Record<string, number>> }>
//     getAttention(id, signal): Promise<AttentionItem[]>
//   }
//   useDeliveryPolling(id: Ref<string>, api: PollingApi, opts?: { onUnauthorized?: () => void }): {
//     view, stats, attention, lastUpdated: Ref<number | null>, stale: Ref<boolean>, polling: Ref<boolean>
//   }
// The first tick runs at once. Cleanup is registered with onScopeDispose,
// so stopping the effect scope (or unmounting) aborts the tick.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { effectScope, nextTick, ref } from 'vue'
import { ApiError } from '../api/client'
import { useDeliveryPolling, type PollingApi } from './useDeliveryPolling'

type Counts = Record<string, number>
const stats = (sms: Counts, email: Counts = {}) => ({ channels: { sms, email } })
const view = (state: string) => ({ campaign: { id: 'c1', state, version: 5 }, revision: null, events: [], generation: null }) as any

interface Deferred<T> {
  promise: Promise<T>
  resolve(v: T): void
  reject(e: unknown): void
}
function deferred<T>(): Deferred<T> {
  let resolve!: (v: T) => void
  let reject!: (e: unknown) => void
  const promise = new Promise<T>((res, rej) => {
    resolve = res
    reject = rej
  })
  return { promise, resolve, reject }
}

// fakeApi answers from mutable state and records every call with its time.
function fakeApi(state: { campaign: string; stats: ReturnType<typeof stats> }) {
  const calls: { fn: string; id: string; at: number; signal: AbortSignal }[] = []
  let inFlight = 0
  let maxInFlight = 0
  const track = async <T>(fn: string, id: string, signal: AbortSignal, value: () => T, delay = 0): Promise<T> => {
    calls.push({ fn, id, at: Date.now(), signal })
    inFlight++
    maxInFlight = Math.max(maxInFlight, inFlight)
    try {
      if (delay) await new Promise((r) => setTimeout(r, delay))
      return value()
    } finally {
      inFlight--
    }
  }
  const delays = { campaign: 0, stats: 0 }
  const api: PollingApi = {
    getCampaign: (id, signal) => track('campaign', id, signal, () => view(state.campaign), delays.campaign),
    getStats: (id, signal) => track('stats', id, signal, () => state.stats, delays.stats),
    getAttention: (id, signal) => track('attention', id, signal, () => []),
  }
  return {
    api,
    calls,
    delays,
    maxInFlight: () => maxInFlight,
    ticks: () => calls.filter((c) => c.fn === 'campaign'),
  }
}

function start(api: PollingApi, id = ref('c1'), opts?: { onUnauthorized?: () => void }) {
  const scope = effectScope()
  const p = scope.run(() => useDeliveryPolling(id, api, opts))!
  return { p, scope, id }
}

beforeEach(() => {
  vi.useFakeTimers()
  vi.setSystemTime(new Date('2026-01-01T00:00:00Z'))
})
afterEach(() => {
  vi.useRealTimers()
})

describe('useDeliveryPolling', () => {
  it('loads the campaign first, then stats and attention in parallel', async () => {
    const f = fakeApi({ campaign: 'sending', stats: stats({ sending: 1 }) })
    const { p, scope } = start(f.api)
    await vi.advanceTimersByTimeAsync(0)
    expect(f.calls[0].fn).toBe('campaign')
    expect(f.calls.slice(1, 3).map((c) => c.fn).sort()).toEqual(['attention', 'stats'])
    expect(p.view.value?.campaign.state).toBe('sending')
    expect(p.stats.value).toEqual(stats({ sending: 1 }))
    expect(p.lastUpdated.value).toBe(Date.now())
    scope.stop()
  })

  it('never overlaps ticks: the next one starts 1 s after the previous finished', async () => {
    const f = fakeApi({ campaign: 'sending', stats: stats({ sending: 1 }) })
    f.delays.campaign = 3000 // slower than the interval
    const { scope } = start(f.api)
    await vi.advanceTimersByTimeAsync(20_000)
    scope.stop()
    expect(f.maxInFlight()).toBeLessThanOrEqual(2) // stats and attention run together, never two ticks
    const t = f.ticks().map((c) => c.at)
    expect(t.length).toBeGreaterThan(2)
    for (let i = 1; i < t.length; i++) expect(t[i] - t[i - 1]).toBe(3000 + 1000)
  })

  it('keeps polling a cancelled campaign while a message is still sending, then runs one final tick', async () => {
    const state = { campaign: 'cancelled', stats: stats({ sending: 1, skipped: 10 }) }
    const f = fakeApi(state)
    const { p, scope } = start(f.api)
    await vi.advanceTimersByTimeAsync(5_500)
    expect(f.ticks().length).toBeGreaterThanOrEqual(5)
    expect(p.polling.value).toBe(true)

    state.stats = stats({ sent: 1, skipped: 10 })
    const before = f.ticks().length
    await vi.advanceTimersByTimeAsync(10_000)
    // The tick that first saw zero in flight, plus one final tick.
    expect(f.ticks().length - before).toBe(2)
    expect(p.polling.value).toBe(false)
    expect(p.stats.value).toEqual(stats({ sent: 1, skipped: 10 }))
    scope.stop()
  })

  it('treats queued and retrying on either channel as in flight', async () => {
    for (const s of [stats({}, { queued: 1 }), stats({ retrying: 2 }), stats({}, { sending: 1 })]) {
      const f = fakeApi({ campaign: 'completed_with_failures', stats: s })
      const { p, scope } = start(f.api)
      await vi.advanceTimersByTimeAsync(3_500)
      expect(f.ticks().length).toBeGreaterThan(2)
      expect(p.polling.value).toBe(true)
      scope.stop()
    }
  })

  it('stops after the final tick for a finished campaign', async () => {
    const f = fakeApi({ campaign: 'completed', stats: stats({ sent: 3 }, { sent: 3 }) })
    const { p, scope } = start(f.api)
    await vi.advanceTimersByTimeAsync(30_000)
    expect(f.ticks().length).toBe(2) // first load, then one final tick
    expect(p.polling.value).toBe(false)
    scope.stop()
  })

  it('backs off 1, 2, 4, 8, 15 s on failure, marks stale, and resets on success', async () => {
    let fail = true
    const f = fakeApi({ campaign: 'sending', stats: stats({ sending: 1 }) })
    const realGet = f.api.getCampaign
    f.api.getCampaign = async (id, signal) => {
      const r = await realGet(id, signal)
      if (fail) throw new TypeError('network down')
      return r
    }
    const { p, scope } = start(f.api)
    await vi.advanceTimersByTimeAsync(0)
    expect(p.stale.value).toBe(true)
    await vi.advanceTimersByTimeAsync(1_000 + 2_000 + 4_000 + 8_000 + 15_000 + 15_000)
    const t = f.ticks().map((c) => c.at - f.ticks()[0].at)
    expect(t).toEqual([0, 1_000, 3_000, 7_000, 15_000, 30_000, 45_000])

    fail = false
    await vi.advanceTimersByTimeAsync(15_000)
    expect(p.stale.value).toBe(false)
    const n = f.ticks().length
    await vi.advanceTimersByTimeAsync(1_000)
    expect(f.ticks().length).toBe(n + 1) // back to the 1 s interval
    scope.stop()
  })

  it('stops on 401 and hands back to the token gate', async () => {
    const onUnauthorized = vi.fn()
    const f = fakeApi({ campaign: 'sending', stats: stats({ sending: 1 }) })
    f.api.getCampaign = async () => {
      throw new ApiError(401, [])
    }
    const { p, scope } = start(f.api, ref('c1'), { onUnauthorized })
    await vi.advanceTimersByTimeAsync(60_000)
    expect(onUnauthorized).toHaveBeenCalledTimes(1)
    expect(p.polling.value).toBe(false)
    expect(f.calls.filter((c) => c.fn === 'stats')).toHaveLength(0)
    scope.stop()
  })

  it('aborts the tick on unmount and discards its late response', async () => {
    const pending = deferred<any>()
    const signals: AbortSignal[] = []
    const api: PollingApi = {
      getCampaign: (_id, signal) => {
        signals.push(signal)
        return pending.promise
      },
      getStats: async () => stats({ sending: 1 }),
      getAttention: async () => [],
    }
    const { p, scope } = start(api)
    await vi.advanceTimersByTimeAsync(0)
    scope.stop()
    expect(signals[0].aborted).toBe(true)
    pending.resolve(view('sending'))
    await vi.advanceTimersByTimeAsync(10_000)
    expect(p.view.value).toBeNull()
    expect(signals).toHaveLength(1)
  })

  it('aborts on campaign switch and ignores the old campaign', async () => {
    const old = deferred<any>()
    const seen: { id: string; signal: AbortSignal }[] = []
    const api: PollingApi = {
      getCampaign: (id, signal) => {
        seen.push({ id, signal })
        return id === 'c1' ? old.promise : Promise.resolve({ ...view('sending'), campaign: { id, state: 'sending', version: 1 } })
      },
      getStats: async () => stats({ sending: 1 }),
      getAttention: async () => [],
    }
    const id = ref('c1')
    const { p, scope } = start(api, id)
    await vi.advanceTimersByTimeAsync(0)
    id.value = 'c2'
    await nextTick()
    await vi.advanceTimersByTimeAsync(0)
    expect(seen[0].signal.aborted).toBe(true)
    old.resolve({ ...view('completed'), campaign: { id: 'c1', state: 'completed', version: 9 } })
    await vi.advanceTimersByTimeAsync(0)
    expect(p.view.value?.campaign.id).toBe('c2')
    scope.stop()
  })
})

