  revisionId: string
  version: number
  segment: unknown
  copy: Draft
}

function baseOf(v: CampaignView): Base | null {
  const r = v.revision
  if (!r) return null
  return {
    revisionId: r.id,
    version: v.campaign.version,
    segment: r.segment,
    copy: { sms: r.sms_body, subject: r.email_subject, body: r.email_body },
