    }
    await router.push(`/campaigns/${v.campaign.id}`)
  } catch (e) {
    issues.value = e instanceof ApiError ? e.issues : [{ path: '', code: 'network', message: String(e) }]
  } finally {
    busy.value = false
  }
}
</script>

